import { replace_words } from '../../core/search';
import * as store from '../../core/store';
import type { CharacterPrefs, TextItem } from '../../core/types';
import { copy_text } from '../clipboard';
import { confirm_dialog, prompt_dialog } from '../dialog';
import { el, on } from '../dom';
import { relative_time } from '../format';
import { icon } from '../icons';
import { toast } from '../toast';

/** 单条文本收藏的详情。正文按角色配置的替换规则过一遍再显示，不改动存下来的原文。 */

export interface TextDetailHandlers {
  on_back: () => void;
  /** 改过或删过之后让外层重新拉数据。 */
  on_changed: () => void;
}

export function render_text_detail(
  item: TextItem,
  prefs: CharacterPrefs,
  handlers: TextDetailHandlers,
): HTMLElement {
  const shown = prefs.replace_enabled ? replace_words(item.content, prefs.replace_rules) : item.content;

  const back = el('button', {
    class: 'yj-iconbtn yj-ws__back',
    html: icon('back', 19),
    title: '返回收藏库',
    attrs: { type: 'button', 'aria-label': '返回收藏库' },
  });
  on<Event>(back, 'click', () => {
    handlers.on_back();
  });

  const head = el('section', { class: 'yj-ws__head' }, [
    back,
    el('div', { class: 'yj-detail__meta' }, [
      el('div', { class: 'yj-row__title', text: item.title || '未命名' }),
      el(
        'div',
        { class: 'yj-row__meta', text: `${relative_time(item.created_at)}${item.source_message_id === null ? '' : `  第 ${item.source_message_id + 1} 楼`}` },
      ),
    ]),
  ]);

  const content = el('article', { class: 'yj-detail__body', text: shown });

  if (prefs.replace_enabled && shown !== item.content) {
    content.append(el('div', { class: 'yj-detail__badge', text: '已按替换规则显示' }));
  }

  const copy_button = el('button', {
    class: 'yj-btn yj-btn--ghost',
    text: '复制全文',
    attrs: { type: 'button' },
  });
  on<Event>(copy_button, 'click', () => {
    void (async () => {
      const ok = await copy_text(shown);
      toast(ok ? '已复制到剪贴板' : '复制失败，请长按选中文字');
    })();
  });

  const rename_button = el('button', {
    class: 'yj-btn yj-btn--ghost',
    text: '重命名',
    attrs: { type: 'button' },
  });
  on<Event>(rename_button, 'click', () => {
    void (async () => {
      const name = await prompt_dialog({
        title: '改标题',
        confirm_text: '保存',
        input: { value: item.title },
      });
      if (name === null) return;
      try {
        await store.put_text({ ...item, title: name || '未命名' });
        toast('标题已更新');
        handlers.on_changed();
      } catch (error) {
        console.warn('[月季管家] 改标题失败', error);
        toast('改标题失败');
      }
    })();
  });

  const delete_button = el('button', {
    class: 'yj-btn yj-btn--danger',
    text: '删除',
    attrs: { type: 'button' },
  });
  on<Event>(delete_button, 'click', () => {
    void (async () => {
      const ok = await confirm_dialog({
        title: '确认删除？',
        message: `「${item.title || '未命名'}」删掉之后就找不回来了。`,
        confirm_text: '删除',
        danger: true,
      });
      if (!ok) return;
      try {
        await store.delete_text(item.id);
        toast('已删除');
        handlers.on_changed();
      } catch (error) {
        console.warn('[月季管家] 删除失败', error);
        toast('删除失败');
      }
    })();
  });

  const actions = el('div', { class: 'yj-detail__actions' }, [copy_button, rename_button, delete_button]);

  return el('section', { class: 'yj-page' }, [head, content, actions]);
}