/** 极简 DOM 构造工具。扩展内不引入前端框架，靠这几个函数保持结构清晰。 */

export interface ElOptions {
  class?: string;
  text?: string;
  html?: string;
  title?: string;
  attrs?: Record<string, string>;
  props?: Record<string, unknown>;
}

export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  options: ElOptions = {},
  children: Array<Node | string> = [],
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (options.class !== undefined) node.className = options.class;
  if (options.text !== undefined) node.textContent = options.text;
  if (options.html !== undefined) node.innerHTML = options.html;
  if (options.title !== undefined) node.title = options.title;
  for (const [key, value] of Object.entries(options.attrs ?? {})) node.setAttribute(key, value);
  const bag = node as unknown as Record<string, unknown>;
  for (const [key, value] of Object.entries(options.props ?? {})) bag[key] = value;
  for (const child of children) node.append(child);
  return node;
}

export function clear(node: Element): void {
  while (node.firstChild) node.removeChild(node.firstChild);
}

export function on<E extends Event>(target: EventTarget, type: string, handler: (event: E) => void): () => void {
  const listener = handler as EventListener;
  target.addEventListener(type, listener);
  return () => target.removeEventListener(type, listener);
}
/** 找到界面根节点的 Shadow DOM 里的内容层。浮动面板、弹窗、提示条都挂在这上面。 */
export function shadow_layer(): HTMLElement | null {
  const host = document.getElementById('yueji-guanjia-host');
  if (!host?.shadowRoot) return null;
  return host.shadowRoot.querySelector('.yj-layer') as HTMLElement | null;
}
