import { layout_shot, type ShotBlock, type ShotLayout, type ShotMeasure, type ShotStyle } from './shot_layout';

/**
 * 把选中的楼层画成一张长图。
 *
 * 这里是自己把正文排版进 canvas，没有引入渲染库。原因：
 * 要的就是「只取正文、去掉状态栏、跨楼层无缝拼成一段连续对话」，
 * 这些对纯文本排版来说都是天然满足的，不需要去啃 DOM 转图片那一堆兼容问题。
 * 代价是图片里是干净的正文，不是聊天界面的像素级复制。
 *
 * 内存控制（手机上最容易出事的地方）：
 * - 先按 1 倍排一遍量出真实高度，再决定用几倍像素密度，尽量取高清但不超过预算。
 * - 单边不超过 MAX_SIDE，总像素不超过 MAX_PIXELS。两个上限都是为了让 iOS 不返回白图。
 * - 万一内容长到连 1 倍都放不下，就按高度截断，并在结果里标明截断了几层。
 */

/** 单边上限。很多设备超过这个尺寸会直接返回空白画布。 */
const MAX_SIDE = 16000;
/** 总像素上限。iOS 上超过这个量级很容易崩。 */
const MAX_PIXELS = 16_000_000;
/** 像素密度候选，从高到低试，取第一个放得下的。 */
const SCALE_STEPS = [2, 1.75, 1.5, 1.25, 1];
/** 量高度时给一个宽松上限，避免超长内容把第一次排版也拖死。 */
const MEASURE_LIMIT = MAX_SIDE * 4;

const SANS = '"PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", system-ui, sans-serif';
const SERIF = '"Songti SC", "Noto Serif SC", "Source Han Serif SC", "SimSun", serif';

export interface ShotTheme {
  background: string;
  ink: string;
  muted: string;
  line: string;
}

export const SHOT_THEMES: Record<'light' | 'dark', ShotTheme> = {
  light: { background: '#ffffff', ink: '#17171a', muted: '#8a8a8e', line: '#e6e6e9' },
  dark: { background: '#141416', ink: '#f1f1f3', muted: '#8f8f96', line: '#2b2b31' },
};

export interface ShotRenderInput {
  blocks: ShotBlock[];
  style: ShotStyle;
  title: string;
  footer: string;
  theme: 'light' | 'dark';
}

export interface ShotRenderResult {
  width: number;
  height: number;
  scale: number;
  blob: Blob | null;
  thumb: Blob | null;
  used_blocks: number;
  total_blocks: number;
  truncated: boolean;
}

function fit(width: number, height: number, scale: number): boolean {
  const w = Math.ceil(width * scale);
  const h = Math.ceil(height * scale);
  return w <= MAX_SIDE && h <= MAX_SIDE && w * h <= MAX_PIXELS;
}

export function choose_scale(width: number, height: number): number | null {
  for (const scale of SCALE_STEPS) {
    if (fit(width, height, scale)) return scale;
  }
  return null;
}

interface Measurer {
  measure: ShotMeasure;
}

/** 造一个离屏画布专门用来量文字宽度。短字符串会缓存，避免逐字测量时反复调用。 */
function make_measurer(): Measurer {
  const canvas = document.createElement('canvas');
  canvas.width = 1;
  canvas.height = 1;
  const context = canvas.getContext('2d');
  if (!context) throw new Error('这台设备不支持画布，没法生成截图');
  const cache = new Map<string, number>();
  const measure: ShotMeasure = (text, size, bold) => {
    const key = text.length <= 2 ? `${size}|${bold ? 1 : 0}|${text}` : '';
    if (key) {
      const hit = cache.get(key);
      if (hit !== undefined) return hit;
    }
    context.font = `${bold ? '600 ' : ''}${size}px ${bold ? SANS : SERIF}`;
    const width = context.measureText(text).width;
    if (key) cache.set(key, width);
    return width;
  };
  return { measure };
}

function to_blob(canvas: HTMLCanvasElement, type: string, quality: number): Promise<Blob | null> {
  return new Promise(resolve => {
    if (typeof canvas.toBlob === 'function') {
      canvas.toBlob(blob => resolve(blob), type, quality);
      return;
    }
    try {
      const url = canvas.toDataURL(type, quality);
      const [, payload] = url.split(',');
      const binary = atob(payload);
      const bytes = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
      resolve(new Blob([bytes], { type }));
    } catch (error) {
      console.warn('[月季管家] 导出图片失败', error);
      resolve(null);
    }
  });
}

/** 列表用的缩略图，只取顶部一段，体积压到很小。 */
async function make_thumb(source: HTMLCanvasElement): Promise<Blob | null> {
  const target_width = 240;
  const target_height = Math.min(400, Math.max(120, Math.round((source.height / source.width) * target_width)));
  const canvas = document.createElement('canvas');
  canvas.width = target_width;
  canvas.height = target_height;
  const context = canvas.getContext('2d');
  if (!context) return null;
  context.fillStyle = '#ffffff';
  context.fillRect(0, 0, target_width, target_height);
  const source_height = Math.min(source.height, Math.round(source.width * (target_height / target_width)));
  context.drawImage(source, 0, 0, source.width, source_height, 0, 0, target_width, target_height);
  return to_blob(canvas, 'image/jpeg', 0.7);
}

export async function render_shot(input: ShotRenderInput): Promise<ShotRenderResult> {
  const { measure } = make_measurer();
  const theme = SHOT_THEMES[input.theme];

  // 第一遍：按 1 倍排出真实高度。
  const probed = layout_shot({ ...input, max_height: MEASURE_LIMIT }, measure);

  let scale = choose_scale(probed.width, probed.height);
  let layout: ShotLayout = probed;
  if (scale === null) {
    // 连 1 倍都放不下：按像素预算截断高度，并只截到设备真的画得出来的长度。
    scale = 1;
    const cap = Math.min(MAX_SIDE, Math.floor(MAX_PIXELS / Math.max(1, probed.width)));
    layout = layout_shot({ ...input, max_height: cap }, measure);
  }

  const pixel_width = Math.max(1, Math.ceil(layout.width * scale));
  const pixel_height = Math.max(1, Math.ceil(layout.height * scale));

  const canvas = document.createElement('canvas');
  canvas.width = pixel_width;
  canvas.height = pixel_height;
  const context = canvas.getContext('2d');
  if (!context) throw new Error('这台设备不支持画布，没法生成截图');

  context.scale(scale, scale);
  context.fillStyle = theme.background;
  context.fillRect(0, 0, layout.width, layout.height);
  context.textBaseline = 'top';

  for (const item of layout.items) {
    if (item.kind === 'divider') {
      context.strokeStyle = theme.line;
      context.lineWidth = 1;
      context.beginPath();
      context.moveTo(item.x, item.y + 0.5);
      context.lineTo(layout.width - item.x, item.y + 0.5);
      context.stroke();
      continue;
    }
    const bold = item.bold ? '600 ' : '';
    const family = item.kind === 'text' ? SERIF : SANS;
    context.font = `${bold}${item.size}px ${family}`;
    context.fillStyle = item.kind === 'name' || item.kind === 'footer' ? theme.muted : theme.ink;
    context.fillText(item.text, item.x, item.y);
  }

  const blob = await to_blob(canvas, 'image/jpeg', 0.9);
  const thumb = await make_thumb(canvas);

  return {
    width: pixel_width,
    height: pixel_height,
    scale,
    blob,
    thumb,
    used_blocks: layout.used_blocks,
    total_blocks: layout.total_blocks,
    truncated: layout.truncated,
  };
}
